// Inventory planning shares the route's existing source choices and browser stock.
let collectionComputing=false;
function collectionEntries(){collectionComputing=true;try{return equipmentEntries(routeCandidates())}finally{collectionComputing=false}}
let mapBatchSelected=new Set(),mapBatchTitle='',mapBatchOpen=false;
function collectionNeeds(){const items=selectedGear(collectionEntries(),'route:'+route),materials=materialTotals(items);return [...items.filter(i=>i.remaining>0).map(i=>({key:'gear:'+i.e.id,kind:'weapon',name:i.e.name,qty:i.remaining,item:i})),...materials.map(t=>({key:'mat:'+t.m[0],kind:'material',name:t.m[0],qty:Math.max(0,t.qty-materialOwned(t.m[0])),material:t.m})).filter(n=>n.qty>0)]}
function collectionRouteSelect(){return `<label class="collection-route">路线 <select data-collection-route aria-label="物资统计路线">${Object.entries(routes).map(([r,n])=>`<option value="${r}" ${r===route?'selected':''}>${n}${r==='救世篇'?'':'篇'}</option>`).join('')}</select></label>`}
function collectionPage(){const cs=routeCandidates(),needs=collectionNeeds();return title('工具','物资统计','按当前培养阵容、获取途径与库存计算缺口。')+`<div class="collection-toolbar">${collectionRouteSelect()}<span class="muted">${cs.length} 名角色 · ${needs.length} 项待收集</span><button type="button" class="button-link" data-map-plan>在地图批量标记 ↗</button></div>${equipmentPlan(collectionEntries(),'route:'+route)}`}
function collectionFold(s){return zh(String(s||'')).replace(/[\s·・•‧，、]/g,'')}
function collectionPinMatches(need,p){const related=atlasRelated(p),terms=materialQueryVariants(need.name).map(collectionFold),matches=n=>terms.some(t=>t&&collectionFold(n).includes(t));if(need.kind==='material')return related.gather.some(g=>matches(g.item))||related.shops.some(s=>s.goods.some(g=>matches(g[0])))||matches(p.info);const source=need.item.source;if(source?.place){const place=collectionFold(source.place),name=collectionFold(p.name);if(place&&name&&(name.includes(place)||place.includes(name)))return true;return false}return related.shops.some(s=>s.goods.some(g=>matches(g[0])))||matches(p.info)}
function collectionMapPlan(needs=collectionNeeds()){const picked=needs.filter(n=>mapBatchSelected.has(n.key)),pool=PINS.filter(p=>route==='救世篇'||p.area===route),groups=new Map(),missing=[];for(const need of picked){const hits=pool.filter(p=>collectionPinMatches(need,p));if(!hits.length)missing.push(need);for(const p of hits){const key=p.x.toFixed(4)+','+p.y.toFixed(4),g=groups.get(key)||{p,needs:[]};if(!g.needs.some(n=>n.key===need.key))g.needs.push(need);groups.set(key,g)}}return {picked,locations:[...groups.values()],missing}}
function mapBatchResults(){if(!MAP_EXTRAS)return '<p class="muted">正在载入店铺与采集资料…</p>';const plan=collectionMapPlan(),group=(mapBatchTitle.trim()||routes[route]+'·收集计划').slice(0,24),saved=mapNotes.filter(n=>n.group===group&&n.route===route).length;return `${saved?`<button type="button" class="text-button map-batch-delete" data-map-batch-delete>删除本组标记（${saved}）</button>`:''}<div class="map-batch-summary"><b>${plan.picked.length} 项物资 · ${plan.locations.length} 处地点</b><button type="button" data-map-batch-save ${plan.locations.length?'':'disabled'}>保存收集标记</button></div>${plan.missing.length?`<p class="map-batch-unmatched">未匹配当前路线地点：${plan.missing.map(n=>esc(n.name)).join('、')}。保留在清单中，不生成点位。</p>`:''}${plan.locations.length?`<div class="map-batch-preview">${plan.locations.map(({p,needs})=>`<button type="button" data-pin="${p.id}"><b>${esc(p.name)}</b><small>${needs.map(n=>esc(n.name)+' × '+n.qty).join('、')}</small></button>`).join('')}</div>`:'<p class="muted">选择缺少的武器或材料，确认地点后保存。</p>'}`}
function mapBatchPanel(){const needs=collectionNeeds(),label=mapBatchTitle||routes[route]+'·收集计划';return `<details class="map-batch-panel" ${mapBatchOpen?'open':''}><summary>批量收集标记 <small>${needs.length} 项缺口</small></summary><div class="map-batch-body">${collectionRouteSelect()}<label class="map-batch-name">标记组名称<input data-map-batch-title maxlength="24" aria-label="标记组名称" value="${escapeAttr(label)}"></label><div class="map-batch-select"><button type="button" data-map-batch-all>全选缺口</button><button type="button" data-map-batch-none>清空选择</button><a href="#collection">管理库存 ↗</a></div><div class="map-batch-needs">${needs.map(n=>`<label><input type="checkbox" data-map-batch-need="${escapeAttr(n.key)}" ${mapBatchSelected.has(n.key)?'checked':''}><span>${esc(n.name)}<small>${n.kind==='weapon'?'武器 / 装备':'材料'}</small></span><b>缺 ${n.qty}</b></label>`).join('')||'<p class="muted">当前阵容库存已齐，或尚未选择需要的装备。</p>'}</div><div id="map-batch-results">${mapBatchResults()}</div></div></details>`}
function paintMapBatch(){const host=document.querySelector('#map-batch-results');if(host)host.innerHTML=mapBatchResults()}
function saveMapBatch(){const plan=collectionMapPlan(),group=(mapBatchTitle.trim()||routes[route]+'·收集计划').slice(0,24);if(!plan.locations.length){toast('请先选择有对应地点的物资');return}const next=[...mapNotes];for(const {p,needs} of plan.locations){const same=next.findIndex(n=>n.group===group&&n.route===route&&Math.abs(n.x-p.x)<.0001&&Math.abs(n.y-p.y)<.0001),note={id:same>=0?next[same].id:'batch-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9),title:needs.map(n=>n.name+' × '+n.qty).join('、').slice(0,32),group,route,items:needs.map(n=>n.name+' × '+n.qty),icon:needs.every(n=>n.kind==='material')?'矿石':'道具',x:p.x,y:p.y};if(same>=0)next[same]=note;else next.push(note)}if(next.length>300){toast('标记最多保存 300 处，请减少选择或删除旧标记');return}if(writeMapNotes(next)){mapBatchTitle=group;mapBatchSelected.clear();paintMapNotes();document.querySelectorAll('[data-map-batch-need]').forEach(el=>{el.checked=false});paintMapBatch();toast('已保存 '+plan.locations.length+' 处收集标记')}}
const collectionMapPage=mapPage;
mapPage=function(){return collectionMapPage().replace('<section class="personal-map-notes">',mapBatchPanel()+'<section class="personal-map-notes">')};
const collectionPaintNotes=paintMapNotes;
paintMapNotes=function(){collectionPaintNotes();paintMapBatch()};
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-map-plan],[data-map-batch-all],[data-map-batch-none],[data-map-batch-save],[data-map-batch-delete]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-map-plan')){mapBatchOpen=true;mapBatchSelected=new Set(collectionNeeds().map(n=>n.key));query='';mapArea=route==='救世篇'?'all':route;mapType='all';mapPurpose='all';location.hash='#map';render()}else if(b.hasAttribute('data-map-batch-save'))saveMapBatch();else if(b.hasAttribute('data-map-batch-delete')){const group=(mapBatchTitle.trim()||routes[route]+'·收集计划').slice(0,24);if(writeMapNotes(mapNotes.filter(n=>(n.group!==group||n.route!==route)))){paintMapNotes();paintMapBatch();toast('已删除该组标记')}}else{mapBatchSelected=b.hasAttribute('data-map-batch-all')?new Set(collectionNeeds().map(n=>n.key)):new Set();document.querySelectorAll('[data-map-batch-need]').forEach(el=>{el.checked=mapBatchSelected.has(el.dataset.mapBatchNeed)});paintMapBatch()}});
document.addEventListener('change',e=>{if(e.target.matches?.('[data-collection-route]')){route=e.target.value;mapBatchSelected.clear();mapBatchTitle='';mapBatchOpen=guidePage()==='map';mapArea=route==='救世篇'?'all':route;persist();render()}else if(e.target.matches?.('[data-map-batch-need]')){const key=e.target.dataset.mapBatchNeed;e.target.checked?mapBatchSelected.add(key):mapBatchSelected.delete(key);paintMapBatch()}});
document.addEventListener('input',e=>{if(e.target.matches?.('[data-map-batch-title]')){mapBatchTitle=e.target.value;paintMapBatch()}});
document.addEventListener('toggle',e=>{if(e.target.matches?.('.map-batch-panel'))mapBatchOpen=e.target.open},true);

if(DB)render();
